// Local stand-in for YomiNinja's Electron main process.
//
// The real app serves the Next.js export from its own HTTP server
// (electron-src/common/server.ts) and exposes every `ipcMain.handle` channel over
// socket.io as well (electron-src/common/ipc_main.ts). The renderer's
// IpcRendererUniversal (renderer/utils/ipc-renderer.ts) uses that socket transport
// whenever it is not running inside Electron. This server reproduces that
// transport: it serves renderer/out and answers the same IPC channels from the
// seeded data in ./data/db.json (generated by seed.js).
//
// Native-only pieces (OCR engines, screen capture, global hotkeys, the Google
// sign-in window, file pickers) are stubbed with realistic responses.

const path = require('path');
const fs = require('fs');
const http = require('http');
const url = require('url');

const REPO = path.resolve(__dirname, '..', 'yomininja-e');
const NM = path.join(REPO, 'node_modules');
const { Server } = require(path.join(NM, 'socket.io'));
const mimeTypes = require(path.join(NM, 'mime-types'));

const PORT = Number(process.env.PORT || 4444);
const PAGES_DIR = path.join(REPO, 'renderer', 'out');
const DB_FILE = path.join(__dirname, 'data', 'db.json');

const db = JSON.parse(fs.readFileSync(DB_FILE, 'utf8'));

// ---------------------------------------------------------------- HTTP
const httpServer = http.createServer((req, res) => {
    const parsed = url.parse(String(req.url), true);
    let pathname = decodeURIComponent(parsed.pathname || '/');

    // The Electron main window loads http://localhost:<port>/index.html
    if (pathname === '/') {
        res.writeHead(302, { Location: '/index.html' });
        return res.end();
    }
    if (pathname.includes('/remote-control')) return res.end();

    let filePath = path.join(PAGES_DIR, path.normalize(pathname));
    if (!filePath.startsWith(PAGES_DIR)) { res.writeHead(403); return res.end(); }
    if (!fs.existsSync(filePath) && fs.existsSync(filePath + '.html')) filePath += '.html';
    if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        return res.end('File not found');
    }
    const type = mimeTypes.lookup(path.extname(filePath));
    res.writeHead(200, type ? { 'Content-Type': type } : {});
    fs.createReadStream(filePath).pipe(res);
});

const io = new Server(httpServer, { cors: { origin: '*', methods: ['GET', 'POST'] }, maxHttpBufferSize: 5e7 });

// ---------------------------------------------------------------- state
const state = {
    activeTab: undefined,
    activeCaptureSource: db.capture_sources.find(s => s.name === db.active_capture_source_name) || db.capture_sources[0],
    activeOcrTemplateId: db.active_ocr_template_id ?? null,
    screenCapturerInterval: 1000,
    googleCookies: db.google_cookies,
};

const clone = (o) => JSON.parse(JSON.stringify(o));
const now = () => new Date().toISOString();

function activePreset() {
    return db.settings_presets.find(p => p.id === db.profile.active_settings_preset_id);
}
function profileJson() {
    const { active_settings_preset_id, ...rest } = db.profile;
    return { ...clone(rest), active_settings_preset: clone(activePreset()) };
}
function broadcast(channel, data) {
    io.sockets.emit(channel, undefined, data);
}
function findTemplate(id) {
    return db.ocr_templates.find(t => t.id === Number(id));
}

const OCR_ENGINE_NAMES = {
    PpOcrAdapter: 'PaddleOCR',
    CloudVisionOcrAdapter: 'Google Cloud Vision',
    GoogleLensOcrAdapter: 'Google Lens',
    MangaOcrAdapter: 'MangaOCR',
    AppleVisionAdapter: 'Apple Vision',
};

// ---------------------------------------------------------------- handlers
const handlers = {
    // profile
    'profile:get_profile': () => profileJson(),
    'profile:change_active_ocr_language': (language) => {
        if (!language) return;
        db.profile.active_ocr_language = language;
        db.profile.updated_at = now();
        broadcast('profile:active_profile', profileJson());
    },
    'profile:change_selected_ocr_engine': (name) => {
        if (!name) return;
        db.profile.selected_ocr_adapter_name = name;
        db.profile.updated_at = now();
    },

    // settings
    'settings_preset:get_active': () => clone(activePreset()),
    'settings_preset:get_default': () => clone(db.settings_presets.find(p => p.name === 'default')),
    'settings_preset:update': (preset) => {
        if (!preset) return { restartOcrAdapter: false };
        const idx = db.settings_presets.findIndex(p => p.id === preset.id);
        if (idx >= 0) db.settings_presets[idx] = { ...preset, updated_at: now() };
        broadcast('settings_preset:active_data', clone(activePreset()));
        return { restartOcrAdapter: false };
    },
    'settings_preset:get_google_cookies': () => clone(state.googleCookies),
    'settings_preset:remove_google_cookies': () => { state.googleCookies = []; },
    'settings_preset:open_google_page': () => {
        // Real app opens a Google sign-in window; pretend the user signed in.
        setTimeout(() => {
            state.googleCookies = clone(db.google_cookies);
            broadcast('settings_preset:google_window_closed');
        }, 800);
    },
    'settings_preset:open_cloud_vision_page': () => {},
    'settings_preset:load_cloud_vision_cred_file': () => {},

    // ocr recognition
    'ocr_recognition:get_supported_languages': () => {
        const engine = db.profile.selected_ocr_adapter_name;
        const names = db.engine_languages[engine] || db.engine_languages.GoogleLensOcrAdapter;
        return db.languages.filter(l => names.includes(l.name));
    },
    'ocr_recognition:get_supported_ocr_engines': () => {
        const out = {};
        for (const n of db.supported_ocr_engines) out[n] = OCR_ENGINE_NAMES[n];
        return out;
    },
    'ocr_recognition:get_hardware_acceleration_options': () => clone(db.hardware_acceleration_options),
    'ocr_recognition:install_hardware_acceleration': async (engineName) => {
        await new Promise(r => setTimeout(r, 1500));
        return true;
    },
    'ocr_recognition:restart_engine': () => {
        setTimeout(() => broadcast('ocr_recognition:ocr_engine_restarted'), 1800);
    },
    'ocr_recognition:get_result': () => null,
    'ocr_recognition:recognize_selection': () => null,

    // app info
    'app_info:get_update_check': () => clone(db.app_info.update_check),
    'app_info:get_system_info': () => clone(db.app_info.system_info),
    'app_info:open_releases_page': () => {},
    'app_info:open_patreon_page': () => {},
    'app_info:open_github_repo_page': () => {},

    // capture sources
    'app:get_capture_sources': (types) => {
        const t = types || ['screen', 'window'];
        return db.capture_sources.filter(s => t.includes(s.type));
    },
    'app:get_active_capture_source': () => state.activeCaptureSource,
    'app:set_capture_source': (source) => {
        if (!source) return;
        state.activeCaptureSource = source;
        broadcast('app:active_capture_source', source);
    },
    'app:editing_ocr_template': () => {},

    // main window
    'main:set_active_tab': (tab) => { state.activeTab = tab; },
    'main:get_active_tab': () => state.activeTab,
    'main:show_capture_source_selection': () => {},
    'main:close_capture_source_selection': () => {},

    // ocr templates
    'ocr_templates:get': (input = {}) => {
        let items = db.ocr_templates;
        if (input?.name) items = items.filter(t => t.name.toLowerCase().includes(String(input.name).toLowerCase()));
        if (input?.capture_source_name) items = items.filter(t => t.capture_source_name === input.capture_source_name);
        return clone(items);
    },
    'ocr_templates:get_active': () => {
        const t = state.activeOcrTemplateId != null ? findTemplate(state.activeOcrTemplateId) : null;
        broadcast('ocr_templates:active_template', t ? clone(t) : null);
        return t ? clone(t) : null;
    },
    'ocr_templates:change_active': (id) => {
        const t = id != null ? findTemplate(id) : null;
        state.activeOcrTemplateId = t ? t.id : null;
        broadcast('ocr_templates:active_template', t ? clone(t) : null);
        return t ? clone(t) : null;
    },
    'ocr_templates:create': (data) => {
        if (!data) return null;
        const id = Math.max(0, ...db.ocr_templates.map(t => t.id)) + 1;
        const t = {
            id, name: data.name,
            image: undefined,
            image_base64: data.image_base64 || db.blank_template_image_base64,
            target_regions: [],
            capture_source_name: data.capture_source_name || state.activeCaptureSource?.name || null,
            capturer_options: data.capturer_options || null,
            created_at: now(), updated_at: now(),
        };
        db.ocr_templates.push(t);
        return clone(t);
    },
    'ocr_templates:delete': (id) => {
        if (Number(id) === state.activeOcrTemplateId) {
            state.activeOcrTemplateId = null;
            broadcast('ocr_templates:active_template', null);
        }
        db.ocr_templates = db.ocr_templates.filter(t => t.id !== Number(id));
    },
    'ocr_templates:update': (data) => {
        if (!data) return;
        const idx = db.ocr_templates.findIndex(t => t.id === data.id);
        if (idx < 0) return;
        const prev = db.ocr_templates[idx];
        const regions = (data.target_regions || []).map(r => {
            const old = prev.target_regions.find(o => o.id === r.id);
            return { ...r, ocr_template_id: data.id, image_base64: r.image_base64 || old?.image_base64 };
        });
        const t = {
            ...prev, ...data,
            image: undefined,
            image_base64: data.image_base64 || prev.image_base64,
            target_regions: regions,
            updated_at: now(),
        };
        db.ocr_templates[idx] = t;
        if (t.id === state.activeOcrTemplateId) broadcast('ocr_templates:active_template', clone(t));
        return clone(t);
    },

    // extensions
    'extensions:get_all_extensions': () => clone(db.extensions),
    'extensions:install_extension': () => {},
    'extensions:uninstall_extension': (ext) => {
        if (!ext) return;
        db.extensions = db.extensions.filter(e => e.id !== ext.id);
    },
    'extensions:clear_extension_data': () => {},
    'extensions:open_extension_options': () => {},
    'extensions:toggle_extension': (ext) => {
        const e = db.extensions.find(x => x.id === ext?.id);
        if (e) e.enabled = !e.enabled;
    },
    'refresh_window': () => {},

    // dictionaries
    'dictionaries:get_all_installed': () => clone(db.dictionaries),
    'dictionaries:delete_all': () => { db.dictionaries = []; },
    'dictionaries:import': () => undefined,
    'dictionaries:search': (text) => {
        if (!text) return [];
        // Longest-prefix match, like the app's headword search.
        const results = [];
        for (let len = Math.min(text.length, 12); len > 0; len--) {
            const sub = text.slice(0, len);
            for (const h of db.headwords) {
                if (h.term === sub || h.reading === sub) results.push(h);
            }
        }
        return clone(results.slice(0, 12));
    },

    // misc
    'screen_capturer:get_interval': () => state.screenCapturerInterval,
    'screen_capturer:set_interval': (v) => { state.screenCapturerInterval = v; },
    'open_link': () => {},
    'user_command:copy_to_clipboard': () => {},
    'overlay:set_ignore_mouse_events': () => {},
    'overlay:set_hovered_text': () => {},
    'overlay:hide_browser_window': () => {},
};

io.on('connect', (socket) => {
    for (const [channel, fn] of Object.entries(handlers)) {
        socket.on(channel, async (data, callback) => {
            try {
                const result = await fn(data);
                if (typeof callback === 'function') callback(result);
            } catch (err) {
                console.error(channel, err);
                if (typeof callback === 'function') callback(undefined);
            }
        });
    }
});

httpServer.listen(PORT, () => {
    console.log(`YomiNinja UI: http://localhost:${PORT}/index.html`);
});

// ---------------------------------------------------------------- VOICEVOX engine stub
// The renderer's VoiceVoxTTS (renderer/context/text-to-speech/voicevox_tts.ts) talks to a
// locally running VOICEVOX engine at http://localhost:50021. Stub the endpoints it uses.
const VOICEVOX_PORT = Number(process.env.VOICEVOX_PORT || 50021);
function silentWav(seconds = 0.6, rate = 24000) {
    const samples = Math.floor(seconds * rate), buf = Buffer.alloc(44 + samples * 2);
    buf.write('RIFF', 0); buf.writeUInt32LE(36 + samples * 2, 4); buf.write('WAVE', 8);
    buf.write('fmt ', 12); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(1, 22);
    buf.writeUInt32LE(rate, 24); buf.writeUInt32LE(rate * 2, 28); buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34);
    buf.write('data', 36); buf.writeUInt32LE(samples * 2, 40);
    return buf;
}
const voicevox = http.createServer((req, res) => {
    const cors = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': '*', 'Access-Control-Allow-Methods': 'GET,POST,OPTIONS' };
    if (req.method === 'OPTIONS') { res.writeHead(204, cors); return res.end(); }
    const p = url.parse(String(req.url), true);
    if (p.pathname === '/speakers') {
        res.writeHead(200, { ...cors, 'Content-Type': 'application/json' });
        return res.end(JSON.stringify(db.voicevox_speakers || []));
    }
    if (p.pathname === '/version') { res.writeHead(200, { ...cors, 'Content-Type': 'application/json' }); return res.end('"0.21.1"'); }
    if (p.pathname === '/audio_query') {
        res.writeHead(200, { ...cors, 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ accent_phrases: [], speedScale: 1, pitchScale: 0, intonationScale: 1, volumeScale: 1,
            prePhonemeLength: 0.1, postPhonemeLength: 0.1, outputSamplingRate: 24000, outputStereo: false, kana: String(p.query.text || '') }));
    }
    if (p.pathname === '/synthesis') { res.writeHead(200, { ...cors, 'Content-Type': 'audio/wav' }); return res.end(silentWav()); }
    res.writeHead(404, cors); res.end();
});
voicevox.on('error', (e) => console.warn(`VOICEVOX stub not started (${e.code})`));
voicevox.listen(VOICEVOX_PORT, '127.0.0.1');
